// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address recipient, uint256 amount) public {
        vm.assume(recipient != address(0));
        uint256 before = c.proposalCount();
        c.newGrantProposal(recipient, amount);
        assertEq(c.proposalCount(), before + 1, "proposalCount must increase by exactly 1");
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address vader, address usdv, address vault) public {
        c.init(vader, usdv, vault);
        assert(c.VADER() == vader && c.USDV() == usdv && c.VAULT() == vault);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address _vader, address _usdv, address _vault) public {
        require(_vader != _usdv);
        c.init(_vader, _usdv, _vault);
        assert(c.VADER() == _vader && c.USDV() == _usdv);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function test(address _vader, address _usdv, address _vault) public {
        c.init(_vader, _usdv, _vault);
        assert(c.USDV() == _usdv);
    }
    receive() external payable {}
    fallback() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function runTest(address _vader, address _usdv, address _vault) public {
        c.init(_vader, _usdv, _vault);
        assert(c.VAULT() == _vault);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function testInit(address _vader, address _usdv, address _vault) public {
        require(_vader != _vault, "addresses must differ");
        c.init(_vader, _usdv, _vault);
        assert(c.VAULT() == _vault);
    }
}

